#!/usr/bin/env bash
# Brook port forwarding manager v2.0.0 — MIT
# Generated by scripts/build.py; edit brook_pf.py instead.
set -euo pipefail
export PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
if ! command -v python3 >/dev/null 2>&1; then
    case "${1:-menu}" in
        install|menu)
            if [[ $(uname -s) != Linux || $EUID -ne 0 ]]; then
                echo "请先安装 Python 3，或在 Linux 上用 sudo 运行安装。" >&2
                exit 1
            fi
            if command -v apt-get >/dev/null 2>&1; then
                apt-get update
                apt-get install -y python3 ca-certificates
            elif command -v dnf >/dev/null 2>&1; then
                dnf install -y python3 ca-certificates
            elif command -v yum >/dev/null 2>&1; then
                yum install -y python3 ca-certificates
            else
                echo "请先安装 Python 3 和 ca-certificates。" >&2
                exit 1
            fi
            ;;
        *) echo "需要 Python 3；请先运行 install。" >&2; exit 1 ;;
    esac
fi
exec python3 /dev/fd/3 "$0" "$@" 3<<'__BROOK_PF_PYTHON__'
#!/usr/bin/env python3
"""Brook port-forward manager. Python 3.6+, Linux/systemd 235+."""
import argparse
import contextlib
import datetime
import fcntl
import hashlib
import ipaddress
import json
import os
from pathlib import Path
import platform
import re
import shutil
import signal
import socket
import subprocess
import sys
import tempfile
import time
import urllib.request

VERSION = "2.0.0"
BASE = Path("/usr/local/brook-pf")
CONF = BASE / "brook.conf"
BIN = BASE / "brook"
MANAGER = BASE / "brook-pf.sh"
UNIT = Path("/etc/systemd/system/brook-pf.service")
INIT = Path("/etc/init.d/brook-pf")
BACKUPS = Path("/var/backups/brook-pf")
SERVICE = "brook-pf.service"
API = "https://api.github.com/repos/txthinking/brook/releases/"
SOURCE = Path(sys.argv.pop(1)).resolve()
sys.argv[0] = str(SOURCE)


def run(args, check=True, **kwargs):
    return subprocess.run([str(x) for x in args], check=check, **kwargs)


def systemctl(*args, **kwargs):
    return run(["systemctl"] + list(args), **kwargs)


def active():
    return systemctl("is-active", "--quiet", SERVICE, check=False).returncode == 0


def enabled():
    return systemctl("is-enabled", "--quiet", SERVICE, check=False,
                     stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode == 0


def port(value):
    value = str(value)
    if not re.fullmatch(r"[0-9]{1,5}", value) or not 1 <= int(value) <= 65535:
        raise ValueError("端口必须为 1–65535 的十进制数字")
    return int(value)


def host(value, ip_only=False):
    if value.startswith("[") and value.endswith("]"):
        value = value[1:-1]
    try:
        # Zone identifiers are intentionally not accepted in this config format.
        if "%" not in value:
            return str(ipaddress.ip_address(value))
    except ValueError:
        pass
    if ip_only:
        raise ValueError("监听地址必须为 IPv4 或 IPv6 地址")
    ascii_host = value.rstrip(".").encode("idna").decode("ascii").lower()
    labels = ascii_host.split(".")
    if (len(ascii_host) > 253 or re.fullmatch(r"[0-9.]+", ascii_host) or
            any(not re.fullmatch(r"[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?", x)
                for x in labels)):
        raise ValueError("目标必须为有效 IP 地址或域名")
    return ascii_host


def parse_config(text):
    rules, seen = [], set()
    for number, line in enumerate(text.splitlines(), 1):
        line = line.split("#", 1)[0].strip()
        if not line:
            continue
        try:
            cols = line.split()
            if len(cols) not in (4, 5):
                raise ValueError("需要 4 或 5 列：本地端口 目标地址 目标端口 启用状态 [监听IP]")
            local, remote, dest, state = cols[:4]
            if state not in ("0", "1"):
                raise ValueError("启用状态只能是 0 或 1")
            rule = (port(local), host(remote), port(dest), int(state),
                    host(cols[4], True) if len(cols) == 5 else "0.0.0.0")
            if rule[0] in seen:
                raise ValueError("本地端口重复：{}".format(rule[0]))
            seen.add(rule[0])
            rules.append(rule)
        except (ValueError, UnicodeError) as exc:
            raise ValueError("配置第 {} 行：{}".format(number, exc))
    return rules


def read_rules(path=None):
    return parse_config((path or CONF).read_text(encoding="utf-8-sig"))


def serialize(rules):
    return "# 本地端口 目标地址 目标端口 启用(1/0) 监听IP\n" + "".join(
        "{} {} {} {} {}\n".format(*rule) for rule in rules)


def endpoint(address, number):
    return "[{}]:{}".format(address, number) if ":" in address else "{}:{}".format(address, number)


def relay_args(rule):
    local, remote, dest, _, listen = rule
    return [str(BIN), "relay", "--from", endpoint(listen, local), "--to", endpoint(remote, dest)]


def atomic_write(path, data, mode=0o644):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, name = tempfile.mkstemp(prefix=".brook-pf-", dir=str(path.parent))
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(data if isinstance(data, bytes) else data.encode("utf-8"))
            stream.flush()
            os.fsync(stream.fileno())
        os.chmod(name, mode)
        os.replace(name, str(path))
    finally:
        if os.path.exists(name):
            os.unlink(name)


def fetch(url, destination, limit=256 * 1024 * 1024):
    if not url.startswith("https://"):
        raise ValueError("下载只允许 HTTPS")
    request = urllib.request.Request(url, headers={"User-Agent": "brook-pf/" + VERSION})
    for attempt in range(3):
        try:
            with urllib.request.urlopen(request, timeout=30) as response:
                if not response.geturl().startswith("https://"):
                    raise ValueError("拒绝降级至非 HTTPS")
                with open(str(destination), "wb") as output:
                    size = 0
                    while True:
                        chunk = response.read(1024 * 1024)
                        if not chunk:
                            break
                        size += len(chunk)
                        if size > limit:
                            raise ValueError("下载文件超过大小限制")
                        output.write(chunk)
            return
        except (OSError, ValueError):
            if attempt == 2:
                raise
            time.sleep(attempt + 1)


def architecture():
    machine = platform.machine().lower()
    mapping = {"x86_64": "amd64", "aarch64": "arm64", "arm64": "arm64",
               "i386": "386", "i686": "386", "armv7l": "arm7", "armv6l": "arm6"}
    if machine not in mapping:
        raise ValueError("暂不支持 CPU 架构：" + machine)
    return mapping[machine]


def release_asset(metadata, arch, requested="latest", checksum=None):
    tag = metadata.get("tag_name", "")
    if not re.fullmatch(r"v[0-9][A-Za-z0-9._-]*", tag):
        raise ValueError("GitHub 返回的版本号无效")
    if requested != "latest" and tag != requested:
        raise ValueError("返回版本与请求版本不符")
    if metadata.get("draft") or metadata.get("prerelease"):
        raise ValueError("只接受正式发布版本")
    name = "brook_linux_" + arch
    matches = [a for a in metadata.get("assets", []) if a.get("name") == name]
    if len(matches) != 1:
        raise ValueError("该版本没有唯一的官方安装包：" + name)
    asset = matches[0]
    expected_url = "https://github.com/txthinking/brook/releases/download/{}/{}".format(tag, name)
    if asset.get("browser_download_url") != expected_url:
        raise ValueError("官方安装包地址不匹配")
    digest = asset.get("digest") or ""
    if checksum:
        checksum = checksum.lower()
        if not re.fullmatch(r"[0-9a-f]{64}", checksum):
            raise ValueError("--sha256 必须为 64 位十六进制摘要")
        if digest and digest != "sha256:" + checksum:
            raise ValueError("指定 SHA256 与 GitHub 发布摘要不一致")
        digest = "sha256:" + checksum
    if not re.fullmatch(r"sha256:[0-9a-f]{64}", digest):
        raise ValueError("此版本未提供 SHA256；请用 --sha256 指定你已独立核实的摘要")
    return tag, expected_url, digest[7:]


def verify_binary(path, checksum):
    digest = hashlib.sha256()
    with open(str(path), "rb") as stream:
        magic = stream.read(4)
        digest.update(magic)
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    if digest.hexdigest() != checksum:
        raise ValueError("SHA256 校验失败；原安装未更改")
    if magic != b"\x7fELF":
        raise ValueError("安装包不是 Linux ELF 程序")
    os.chmod(str(path), 0o755)
    help_text = run([path, "relay", "--help"], stdout=subprocess.PIPE,
                    stderr=subprocess.STDOUT, timeout=15).stdout.decode("utf-8", "replace")
    if "--from" not in help_text or "--to" not in help_text:
        raise ValueError("该 Brook 版本不支持所需 relay 命令")


def stage_binary(directory, version="latest", checksum=None):
    if version != "latest" and not re.fullmatch(r"v[0-9][A-Za-z0-9._-]*", version):
        raise ValueError("版本号示例：v20270101")
    metadata_path = directory / "release.json"
    fetch(API + ("latest" if version == "latest" else "tags/" + version), metadata_path, 4 * 1024 * 1024)
    tag, url, digest = release_asset(json.loads(metadata_path.read_text()), architecture(), version, checksum)
    print("下载并校验 Brook {} ({})…".format(tag, architecture()), flush=True)
    candidate = directory / "brook"
    fetch(url, candidate)
    verify_binary(candidate, digest)
    return candidate, {"version": tag, "sha256": digest, "asset": url, "manager": VERSION}


def get_cron():
    if not shutil.which("crontab"):
        return None
    result = run(["crontab", "-l"], check=False, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                 env=dict(os.environ, LC_ALL="C"))
    if result.returncode:
        if b"no crontab" in result.stderr.lower():
            return None
        raise RuntimeError("读取 root crontab 失败：" + result.stderr.decode("utf-8", "replace"))
    return result.stdout.decode("utf-8")


def without_old_monitor(text):
    return "".join(line for line in text.splitlines(True)
                   if line.lstrip().startswith("#") or not re.search(
                       r"(?:^|[\s/])brook-pf\.sh\s+monitor(?:\s|$)", line))


def legacy_pids():
    found = []
    for process in Path("/proc").glob("[0-9]*"):
        try:
            executable = os.readlink(str(process / "exe"))
            args = (process / "cmdline").read_bytes().split(b"\0")
            if executable in (str(BIN), str(BIN) + " (deleted)") and b"relays" in args:
                found.append(int(process.name))
        except (OSError, ValueError):
            continue
    return found


def stop_legacy():
    pids = legacy_pids()
    for pid in pids:
        with contextlib.suppress(ProcessLookupError):
            os.kill(pid, signal.SIGTERM)
    for _ in range(50):
        if not set(pids).intersection(legacy_pids()):
            return
        time.sleep(0.1)
    raise RuntimeError("旧 Brook 进程未退出，迁移取消；请先检查旧服务")


def unit_text():
    return """# Managed by brook-pf v2
[Unit]
Description=Brook TCP/UDP port forwarding
Wants=network-online.target
After=network-online.target
StartLimitIntervalSec=60
StartLimitBurst=5

[Service]
Type=notify
NotifyAccess=main
ExecStart=/bin/bash /usr/local/brook-pf/brook-pf.sh run
Restart=on-failure
RestartSec=3
TimeoutStartSec=30
TimeoutStopSec=15
KillMode=control-group
DynamicUser=yes
AmbientCapabilities=CAP_NET_BIND_SERVICE
CapabilityBoundingSet=CAP_NET_BIND_SERVICE
NoNewPrivileges=yes
PrivateTmp=yes
ProtectHome=yes
ProtectSystem=strict
LimitNOFILE=65536

[Install]
WantedBy=multi-user.target
"""


class Transaction:
    """Keep a persistent, exact snapshot before touching managed state."""
    def __init__(self, paths, migration=False):
        BACKUPS.mkdir(parents=True, exist_ok=True, mode=0o700)
        os.chmod(str(BACKUPS), 0o700)
        self.directory = Path(tempfile.mkdtemp(prefix=datetime.datetime.now().strftime("%Y%m%d-%H%M%S-"), dir=str(BACKUPS)))
        self.was_active = active() or bool(legacy_pids())
        self.was_enabled = enabled()
        self.cron = get_cron() if migration else None
        self.cron_changed = False
        self.snapshots = []
        for index, path in enumerate(paths):
            item = {"path": str(path), "file": str(index), "exists": path.exists() or path.is_symlink()}
            if path.is_symlink():
                item["link"] = os.readlink(str(path))
            elif path.exists():
                shutil.copy2(str(path), str(self.directory / str(index)))
            self.snapshots.append(item)
        atomic_write(self.directory / "manifest.json", json.dumps({
            "active": self.was_active, "enabled": self.was_enabled,
            "files": self.snapshots, "cron": self.cron}, ensure_ascii=False, indent=2), 0o600)
        print("备份：" + str(self.directory), flush=True)

    def remove_monitor(self):
        if self.cron is not None:
            cleaned = without_old_monitor(self.cron)
            if cleaned != self.cron:
                self.cron_changed = True
                run(["crontab", "-"], input=cleaned.encode("utf-8"))

    def rollback(self):
        print("操作失败，恢复原文件与服务状态…", file=sys.stderr)
        if UNIT.exists() and "# Managed by brook-pf v2" in UNIT.read_text():
            systemctl("stop", SERVICE, check=False)
            # Remove new enable links BEFORE restoring a legacy init script.
            systemctl("disable", SERVICE, check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        for item in self.snapshots:
            target = Path(item["path"])
            if target.is_symlink() or target.exists():
                target.unlink()
            if "link" in item:
                target.symlink_to(item["link"])
            elif item["exists"]:
                shutil.copy2(str(self.directory / item["file"]), str(target))
        if self.cron_changed:
            run(["crontab", "-"], input=self.cron.encode("utf-8"))
        systemctl("daemon-reload")
        systemctl("reset-failed", SERVICE, check=False)
        # Legacy boot links have already been restored exactly; do not invoke
        # distro-specific SysV registration helpers again.
        if self.was_enabled and UNIT.exists():
            systemctl("enable", SERVICE)
        if self.was_active:
            systemctl("start", SERVICE)

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, tb):
        if exc_type:
            try:
                self.rollback()
            except Exception as restore_error:
                print("自动恢复失败：{}；备份保留于 {}".format(restore_error, self.directory), file=sys.stderr)
        return False


def installed():
    return MANAGER.exists() and UNIT.exists() and BIN.exists()


def install(version="latest", checksum=None, preserve_state=False):
    source_bytes = SOURCE.read_bytes()
    if not source_bytes.startswith(b"#!/usr/bin/env bash"):
        raise ValueError("请运行生成的 brook-pf.sh 安装")
    rules = read_rules() if CONF.exists() else []
    is_old = INIT.exists() or bool(legacy_pids())
    if UNIT.exists() and "# Managed by brook-pf v2" not in UNIT.read_text():
        raise ValueError("存在非本脚本管理的原生 systemd 单元，请先人工检查 " + str(UNIT))
    with tempfile.TemporaryDirectory(prefix="brook-pf-") as directory:
        candidate, metadata = stage_binary(Path(directory), version, checksum)
        BASE.mkdir(parents=True, exist_ok=True, mode=0o755)
        os.chmod(str(BASE), 0o755)
        paths = [BIN, CONF, MANAGER, UNIT, BASE / "installed.json", INIT]
        # Preserve SysV enable links; do not let systemctl execute the legacy stop script.
        paths += sorted(Path("/etc").glob("rc?.d/*brook-pf"))
        with Transaction(paths, migration=True) as transaction:
            transaction.remove_monitor()
            if is_old:
                stop_legacy()
                if INIT.exists():
                    INIT.unlink()
                for path in paths[6:]:
                    if path.is_symlink():
                        path.unlink()
                systemctl("daemon-reload")
            else:
                systemctl("stop", SERVICE, check=False, stderr=subprocess.DEVNULL)
            atomic_write(BIN, candidate.read_bytes(), 0o755)
            atomic_write(CONF, serialize(rules))
            atomic_write(MANAGER, source_bytes, 0o755)
            atomic_write(UNIT, unit_text())
            atomic_write(BASE / "installed.json", json.dumps(metadata, indent=2) + "\n")
            if shutil.which("restorecon"):
                run(["restorecon", "-RF", BASE, UNIT])
            systemctl("daemon-reload")
            # The new unit has no legacy ExecStop, so this cannot call its broad pkill/grep logic.
            systemctl("stop", SERVICE, check=False)
            if not preserve_state or transaction.was_enabled:
                systemctl("enable", SERVICE)
            systemctl("reset-failed", SERVICE, check=False)
            if not preserve_state or transaction.was_active:
                systemctl("start", SERVICE)
                if not active():
                    raise RuntimeError("新服务启动失败")
    print("安装/升级完成：{}；保留 {} 条规则。".format(metadata["version"], len(rules)))
    print("TCP/UDP 入站端口还需按实际防火墙及云安全组放行；使用 firewall 命令查看。")


def save_rules(rules):
    # Validate even callers that construct rules directly.
    data = serialize(rules)
    parse_config(data)
    with Transaction([CONF]) as transaction:
        atomic_write(CONF, data)
        if transaction.was_active:
            # Explicit user edits must not consume the crash-loop restart budget.
            systemctl("reset-failed", SERVICE, check=False)
            systemctl("restart", SERVICE)
            if not active():
                raise RuntimeError("新配置启动失败")
    print("配置已保存" + ("并应用。" if transaction.was_active else "；服务当前停止，启动后生效。"))


def edit_rule(action, local, remote=None, dest=None, listen="0.0.0.0", state=1, new_port=None):
    local = port(local)
    rules = read_rules()
    matches = [i for i, rule in enumerate(rules) if rule[0] == local]
    if action == "add":
        if matches:
            raise ValueError("本地端口已存在")
        rules.append((local, host(remote), port(dest), state, host(listen, True)))
    else:
        if not matches:
            raise ValueError("本地端口不存在")
        index = matches[0]
        if action == "delete":
            del rules[index]
        elif action == "set":
            rules[index] = (port(new_port or local), host(remote), port(dest), state, host(listen, True))
        else:
            rule = list(rules[index])
            rule[3] = int(action == "enable")
            rules[index] = tuple(rule)
    save_rules(rules)


def notify_ready():
    address = os.environ.get("NOTIFY_SOCKET")
    if address:
        if address.startswith("@"):
            address = "\0" + address[1:]
        with socket.socket(socket.AF_UNIX, socket.SOCK_DGRAM) as sock:
            sock.connect(address)
            sock.sendall(b"READY=1")


def relay_is_listening(pid, local_port):
    """Confirm both sockets belong to this child, not an unrelated port owner."""
    inodes = set()
    try:
        for fd in Path("/proc/{}/fd".format(pid)).iterdir():
            try:
                link = os.readlink(str(fd))
                if link.startswith("socket:["):
                    inodes.add(link[8:-1])
            except FileNotFoundError:
                pass
    except FileNotFoundError:
        return False
    found = set()
    for proto in ("tcp", "tcp6", "udp", "udp6"):
        path = Path("/proc/net") / proto
        if not path.exists():
            continue
        for line in path.read_text().splitlines()[1:]:
            fields = line.split()
            if (len(fields) > 9 and fields[9] in inodes and
                    int(fields[1].rsplit(":", 1)[1], 16) == local_port and
                    fields[3] == ("0A" if proto.startswith("tcp") else "07")):
                found.add(proto.rstrip("6"))
    return found == {"tcp", "udp"}


def supervise():
    children, ports, stopping = [], [], [False]

    def stop(signum, frame):
        stopping[0] = True

    signal.signal(signal.SIGTERM, stop)
    signal.signal(signal.SIGINT, stop)
    try:
        for rule in read_rules():
            if rule[3]:
                print("转发 {} -> {} (TCP/UDP)".format(endpoint(rule[4], rule[0]), endpoint(rule[1], rule[2])), flush=True)
                children.append(subprocess.Popen(relay_args(rule)))
                ports.append(rule[0])
        started, ready = time.monotonic(), False
        while not stopping[0]:
            for child in children:
                if child.poll() is not None:
                    raise RuntimeError("Brook 子进程退出（{}），systemd 将重启服务".format(child.returncode))
            if not ready:
                if all(relay_is_listening(child.pid, number) for child, number in zip(children, ports)):
                    notify_ready()
                    ready = True
                elif time.monotonic() - started >= 20:
                    raise RuntimeError("Brook 未能在 20 秒内建立全部 TCP/UDP 监听")
            time.sleep(0.1)
    finally:
        for child in children:
            if child.poll() is None:
                child.terminate()
        deadline = time.monotonic() + 8
        for child in children:
            try:
                child.wait(timeout=max(0.1, deadline - time.monotonic()))
            except subprocess.TimeoutExpired:
                child.kill()
                child.wait()


def firewall(local=None, apply=False):
    ports = [port(local)] if local else [rule[0] for rule in read_rules() if rule[3]]
    commands = []
    if shutil.which("firewall-cmd") and run(["firewall-cmd", "--state"], check=False,
                                            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode == 0:
        for number in ports:
            for proto in ("tcp", "udp"):
                # Apply only these rules, without reloading unrelated runtime rules.
                commands += [["firewall-cmd", "--permanent", "--add-port={}/{}".format(number, proto)],
                             ["firewall-cmd", "--add-port={}/{}".format(number, proto)]]
    elif shutil.which("ufw") and "Status: active" in run(
            ["ufw", "status"], stdout=subprocess.PIPE, env=dict(os.environ, LC_ALL="C")).stdout.decode():
        commands = [["ufw", "allow", "{}/{}".format(number, proto)] for number in ports for proto in ("tcp", "udp")]
    else:
        print("未检测到活动的 firewalld/UFW。请按现有 nftables/iptables 策略放行 TCP 和 UDP：" + ", ".join(map(str, ports)))
        if apply:
            raise ValueError("未自动修改防火墙；请按系统现有策略配置")
    for command in commands:
        print(" ".join(command))
        if apply:
            run(command)
    print("云服务器还需在控制台安全组放行相同端口。")


def uninstall():
    # Keep user config and snapshots; remove only manager-owned executable/unit files.
    with Transaction([BIN, MANAGER, UNIT, BASE / "installed.json"]):
        systemctl("disable", "--now", SERVICE)
        for path in (BIN, MANAGER, UNIT, BASE / "installed.json"):
            if path.exists():
                path.unlink()
        systemctl("daemon-reload")
    print("已卸载服务和程序；brook.conf、备份及防火墙规则保留。")


def requirements():
    if platform.system() != "Linux":
        raise ValueError("安装/管理服务需要 Linux；macOS 可运行 check/help 及测试")
    if os.geteuid() != 0:
        raise ValueError("请使用 sudo bash brook-pf.sh …")
    if not Path("/run/systemd/system").is_dir() or not shutil.which("systemctl"):
        raise ValueError("需要以 systemd 作为 init 的 Linux 系统")
    result = run(["systemctl", "--version"], stdout=subprocess.PIPE).stdout.decode()
    if int(result.split()[1]) < 235:
        raise ValueError("需要 systemd >= 235；旧 CentOS 7 不在支持范围")


def parser():
    p = argparse.ArgumentParser(description="Brook TCP/UDP 端口转发管理器 v" + VERSION)
    p.add_argument("--version", action="version", version=VERSION)
    sub = p.add_subparsers(dest="command")
    for name in ("install", "update"):
        item = sub.add_parser(name, help="安装/迁移" if name == "install" else "更新 Brook 和当前管理脚本")
        item.add_argument("version", nargs="?", default="latest")
        item.add_argument("--sha256")
    for name in ("add", "set"):
        item = sub.add_parser(name, help="添加规则" if name == "add" else "修改规则")
        item.add_argument("port")
        item.add_argument("host")
        item.add_argument("target_port")
        item.add_argument("--listen", default="0.0.0.0")
        item.add_argument("--disabled", action="store_true")
        if name == "set":
            item.add_argument("--new-port")
    for name in ("delete", "enable", "disable"):
        item = sub.add_parser(name)
        item.add_argument("port")
    item = sub.add_parser("check", help="只校验配置，不修改系统")
    item.add_argument("file", nargs="?", default=str(CONF))
    item = sub.add_parser("firewall", help="输出放行命令；--apply 才实际执行")
    item.add_argument("port", nargs="?")
    item.add_argument("--apply", action="store_true")
    item = sub.add_parser("uninstall")
    item.add_argument("--yes", action="store_true")
    for name in ("list", "start", "stop", "restart", "status", "logs", "run", "menu", "monitor"):
        sub.add_parser(name)
    return p


def menu():
    print("\nBrook 端口转发管理 v{}\n1. 安装/迁移  2. 更新 Brook  3. 卸载\n4. 启动  5. 停止  6. 重启\n7. 管理规则  8. 查看规则  9. 日志\n10. 状态  11. 防火墙  0. 退出".format(VERSION))
    answer = input("请选择：").strip()
    simple = {"1": "install", "2": "update", "3": "uninstall", "4": "start", "5": "stop",
              "6": "restart", "8": "list", "9": "logs", "10": "status", "11": "firewall"}
    if answer == "0":
        return
    if answer in simple:
        main([simple[answer]])
    elif answer == "7":
        operation = input("1. 添加  2. 删除  3. 修改  4. 启用  5. 禁用：").strip()
        actions = {"1": "add", "2": "delete", "3": "set", "4": "enable", "5": "disable"}
        if operation not in actions:
            raise ValueError("无效选项")
        args = [actions[operation], input("本地端口：").strip()]
        if operation in ("1", "3"):
            args += [input("目标 IP/域名：").strip(), input("目标端口：").strip(),
                     "--listen", input("监听 IP [0.0.0.0]：").strip() or "0.0.0.0"]
            if input("立即启用？[Y/n]：").strip().lower() == "n":
                args.append("--disabled")
            if operation == "3":
                new_port = input("新本地端口 [留空保持]：").strip()
                if new_port:
                    args += ["--new-port", new_port]
        main(args)
    else:
        raise ValueError("无效选项")


def main(argv=None):
    args = parser().parse_args(argv)
    command = args.command or "menu"
    if command == "menu":
        return menu()
    if command == "check":
        print("配置有效：{} 条规则".format(len(read_rules(Path(args.file)))))
        return
    if command == "run":
        return supervise()
    if command == "monitor":
        # An already-running old cron command must not re-enter legacy management.
        print("运行监控由 systemd 自动重启机制接管，无需 cron。")
        return
    if command == "list":
        print(serialize(read_rules()), end="")
        return
    requirements()
    # One writer at a time; service children must not inherit this lock.
    with open("/run/lock/brook-pf.lock", "a") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        if command == "install":
            return install(args.version, args.sha256)
        if not installed():
            raise ValueError("请先执行 install（旧安装会自动迁移）")
        if command == "update":
            return install(args.version, args.sha256, preserve_state=True)
        if command in ("add", "set", "delete", "enable", "disable"):
            return edit_rule(command, args.port, getattr(args, "host", None),
                             getattr(args, "target_port", None), getattr(args, "listen", "0.0.0.0"),
                             int(not getattr(args, "disabled", False)), getattr(args, "new_port", None))
        if command in ("start", "restart"):
            read_rules()
            systemctl("reset-failed", SERVICE, check=False)
            return systemctl(command, SERVICE)
        if command == "stop":
            return systemctl("stop", SERVICE)
        if command == "status":
            raise SystemExit(systemctl("status", "--no-pager", SERVICE, check=False).returncode)
        if command == "logs":
            # Release the writer lock before following logs indefinitely.
            fcntl.flock(lock, fcntl.LOCK_UN)
            return run(["journalctl", "-u", SERVICE, "-n", "100", "-f"])
        if command == "firewall":
            return firewall(args.port, args.apply)
        if command == "uninstall":
            if args.yes or input("确认卸载？保留配置和备份 [y/N]：").strip().lower() == "y":
                return uninstall()


def entry():
    try:
        main()
    except KeyboardInterrupt:
        raise SystemExit(130)
    except Exception as exc:
        print("错误：{}".format(exc), file=sys.stderr)
        raise SystemExit(1)


if __name__ == "__main__":
    entry()

__BROOK_PF_PYTHON__
